void Solver::bump_var(int var, double coeff) {
    // add increment
    double inc = var_inc * coeff;
    activity[var] += inc;

    // static counter to limit full rescales
    static unsigned long long bump_counter = 0;
    ++bump_counter;

    // trigger a full rescale only when necessary and not too often
    const double OVERFLOW_THRESH = 1e100;
    const double SCALE_FACTOR    = 1e-100;
    const unsigned long long RESCALE_PERIOD = 1024ULL; // every 1024 bumps at most

    bool need_rescale = (activity[var] > OVERFLOW_THRESH) || (var_inc > OVERFLOW_THRESH);
    if (need_rescale && (bump_counter % RESCALE_PERIOD == 0)) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE_FACTOR;
        var_inc *= SCALE_FACTOR;
    } else if (need_rescale) {
        // cap the offending value to avoid immediate overflow
        if (activity[var] > OVERFLOW_THRESH) activity[var] = OVERFLOW_THRESH;
        if (var_inc > OVERFLOW_THRESH) var_inc = OVERFLOW_THRESH;
    }

    // keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
